# ---------------------------------------------------------------------------
# the frozen root formula, implemented independently from the primary source
# ---------------------------------------------------------------------------

FRAMING_SEMANTIC = "a65d17669c77c27559f091d69b03b52d4cb303fbb6c961e59c7c99d1216f243a"
FRAMING_CODE = "991fadb2d273890d5c0f472ba36869e0af62d3872ef2c1aee6a570fd17ddd167"
KERNEL_SEMANTIC = "3332cc2e53ae1e2f53d63b8bf8c56b2840169682f27ca7bff055000b90b55cc8"
KERNEL_CODE = "4aba65b4297d62d45873595ab44db403c9c6cc2cce1e5c497d99f975f78abd79"
SIGNAL_DOMAIN = "iwm-atlas-v2-causal-intrabar-signal-sequence-v1"


def _text_term(value: str) -> bytes:
    """A length-prefixed text term: be64(len) || bytes."""
    raw = value.encode("ascii")
    return struct.pack(">Q", len(raw)) + raw


def _digest_term(value: str) -> bytes:
    """A digest term: the 32 RAW bytes, with no length prefix."""
    if len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
        raise ValueError(f"noncanonical digest {value}")
    return bytes.fromhex(value)


def signal_image(fields: list[str]) -> bytes:
    """The 24-term hash image of one event-signal row."""
    if len(fields) != 40:
        raise ValueError("event rows carry exactly 40 cells")
    out = bytearray()
    out += _digest_term(fields[2])   # signal_id
    out += _digest_term(fields[3])   # physical_event_id
    out += _digest_term(fields[4])   # policy_id
    out += _digest_term(fields[7])   # causal_run_prefix_root
    out += struct.pack(">I", int(fields[8]))          # continuity_ordinal
    out += bytes([{"LOW": 0, "HIGH": 1}[fields[9]]])  # extreme_side
    out += struct.pack(">q", int(fields[10]))         # pivot_price_u6
    out += _digest_term(fields[11])                   # pivot_evidence_root
    out += struct.pack(">Q", int(fields[17]))         # confirmation_state_position
    out += struct.pack(">Q", int(fields[18]))         # confirmation_group_ordinal
    out += struct.pack(">q", int(fields[19]))         # confirmation_ts_ns
    out += struct.pack(">q", int(fields[20]))         # causal_visible_ts_ns
    out += bytes([1 if fields[23] == "true" else 0])  # pivot_retouch_order_uncertain
    for cell in (fields[24], fields[25]):             # the two optional delays
        if cell == "NA":
            out += bytes([0])
        else:
            out += bytes([1]) + struct.pack(">I", int(cell))
    out += struct.pack(">q", int(fields[26]))         # latency_from_pivot_ns_min
    out += struct.pack(">q", int(fields[27]))         # latency_from_pivot_ns_max
    out += struct.pack(">Q", int(fields[28]))         # latency_from_pivot_groups_min
    out += struct.pack(">Q", int(fields[29]))         # latency_from_pivot_groups_max
    out += struct.pack(">q", int(fields[31]))         # confirmation_price_low_u6
    out += struct.pack(">q", int(fields[32]))         # confirmation_price_high_u6
    out += struct.pack(">I", int(fields[33]))         # confirmation_crossing_count
    out += _digest_term(fields[34])                   # confirmation_crossing_set_root
    out += _digest_term(fields[35])                   # confirmation_group_root
    return bytes(out)


def session_root(rows: list[list[str]]) -> str:
    """The session's signal_sequence_root over its rows, in file order."""
    hasher = hashlib.sha256()
    hasher.update(_text_term(FRAMING_SEMANTIC))
    hasher.update(_text_term(FRAMING_CODE))
    hasher.update(_text_term(SIGNAL_DOMAIN))
    hasher.update(_text_term(KERNEL_SEMANTIC))
    hasher.update(_text_term(KERNEL_CODE))
    hasher.update(struct.pack(">Q", len(rows)))
    for row in rows:
        hasher.update(signal_image(row))
    return hasher.hexdigest()


