def digest(label: str) -> str:
    """A stable canonical 64-hex id for a fixture entity."""
    return hashlib.sha256(("qr_candidates_fixture:" + label).encode("ascii")).hexdigest()


# ---------------------------------------------------------------------------
# a parameterised BYTE_ARRAY parquet writer (multi row group, real statistics)
# ---------------------------------------------------------------------------


def write_parquet(path: str, names: list[str], values: dict[str, list], group_sizes: list[int],
                  stats_for: set[str], stats_override: dict | None = None,
                  repetition: int = REP_REQUIRED, codec: int = CODEC_ZSTD,
                  physical_override: tuple | None = None,
                  converted_override: tuple | None = None) -> None:
    """Writes one BYTE_ARRAY/UTF8 column per name, ZSTD, DataPage v1.

    REPETITION IS REQUIRED BY DEFAULT, because that is what the bound
    publications measurably are (tests/fixtures/publication_repetition_census.tsv:
    24/24 and 26/26 leaves REQUIRED). A REQUIRED leaf carries no definition
    levels and no nulls, so ``values[name][row]`` must be a ``str``; the
    OPTIONAL variant exists only so the PUBLICATION profile has something
    lawful-elsewhere to refuse.

    ``stats_override`` maps (name, group) -> (min_bytes, max_bytes) so a fixture
    can carry statistics that DISAGREE with its own values. ``physical_override``
    and ``converted_override`` are (name, value) pairs that mis-declare ONE
    leaf, so a profile gate can be exercised without a second writer.
    """
    total = sum(group_sizes)
    for name in names:
        if len(values[name]) != total:
            raise ValueError(f"column {name} has {len(values[name])} values, expected {total}")
        if repetition == REP_REQUIRED and any(v is None for v in values[name]):
            raise ValueError(f"column {name} carries a null in a REQUIRED leaf")
    stats_override = stats_override or {}

    body = bytearray(MAGIC)
    row_group_structs: list[Compact] = []
    lo = 0
    for group, size in enumerate(group_sizes):
        hi = lo + size
        chunk_structs: list[Compact] = []
        group_bytes = 0
        for name in names:
            chunk_start = len(body)
            window = values[name][lo:hi]
            present = [v for v in window if v is not None]
            value_bytes = plain_byte_array([v.encode("utf-8") for v in present])
            if repetition == REP_REQUIRED:
                # max definition level 0: the page carries values and nothing else.
                raw = value_bytes
            else:
                levels = [0 if v is None else 1 for v in window]
                level_bytes = hybrid(levels, 1, "rle")
                raw = struct.pack("<I", len(level_bytes)) + level_bytes + value_bytes
            packed = zstd_compress(raw)
            header = page_header_v1(len(raw), len(packed), size, ENC_PLAIN)
            data_offset = len(body)
            body += header
            body += packed
            chunk_uncompressed = len(header) + len(raw)
            total_compressed = len(body) - chunk_start
            meta = (
                Compact()
                .i32(1, physical_override[1]
                     if physical_override and physical_override[0] == name else TYPE_BYTE_ARRAY)
                .i32_list(2, [ENC_RLE, ENC_PLAIN])
                .text_list(3, [name])
                .i32(4, codec)
                .i64(5, size)
                .i64(6, chunk_uncompressed)
                .i64(7, total_compressed)
                .i64(9, data_offset)
            )
            if name in stats_for:
                key = (name, group)
                if key in stats_override:
                    min_bytes, max_bytes = stats_override[key]
                elif present:
                    encoded = sorted(v.encode("utf-8") for v in present)
                    min_bytes, max_bytes = encoded[0], encoded[-1]
                else:
                    min_bytes = max_bytes = b""
                stats = (
                    Compact()
                    .i64(3, len(window) - len(present))
                    .binary(5, max_bytes)
                    .binary(6, min_bytes)
                )
                meta.struct(12, stats)
            chunk_structs.append(Compact().i64(2, chunk_start).struct(3, meta))
            group_bytes += total_compressed
        row_group_structs.append(
            Compact().struct_list(1, chunk_structs).i64(2, group_bytes).i64(3, size)
        )
        lo = hi

    schema_structs = [Compact().text(4, "arrow_schema").i32(5, len(names))]
    for name in names:
        element = Compact()
        physical = (physical_override[1]
                    if physical_override and physical_override[0] == name else TYPE_BYTE_ARRAY)
        element.i32(1, physical).i32(3, repetition).text(4, name)
        converted = (converted_override[1]
                     if converted_override and converted_override[0] == name else CONVERTED_UTF8)
        if converted is not None:
            element.i32(6, converted)
        schema_structs.append(element)
    footer = (
        Compact()
        .i32(1, 2)
        .struct_list(2, schema_structs)
        .i64(3, total)
        .struct_list(4, row_group_structs)
        .text(6, "qr_candidates_fixture_generator")
        .done()
    )
    with open(path, "wb") as handle:
        handle.write(bytes(body) + footer + struct.pack("<I", len(footer)) + MAGIC)


