DAYS = ["2022-01-03", "2022-01-04", "2022-01-05", "2022-01-06", "2022-01-07", "2022-01-10"]
N_SESSIONS = len(DAYS)
#: The prefix stop used by the tests. Sessions 4 and 5 exist BEYOND it, so a
#: reader that oversteps by one byte is observable.
STOP_ORDINAL = 3


def event_row(ordinal: int, day: str, label: str, physical: str, policy: str, reversal: int,
              side: str, visible: int, absent_delays: bool = False) -> list[str]:
    """One event_signals row: 40 cells, every hashed cell a real value."""
    return [
        str(ordinal),                       # 0 ordinal
        day,                                # 1 day
        digest(label),                      # 2 signal_id
        physical,                           # 3 physical_event_id
        digest("policy:" + policy),         # 4 policy_id
        policy,                             # 5 policy_name
        str(reversal),                      # 6 reversal_bps
        digest("run:" + label),             # 7 causal_run_prefix_root
        "0",                                # 8 continuity_ordinal
        side,                               # 9 extreme_side
        "223695000",                        # 10 pivot_price_u6
        digest("pivot:" + label),           # 11 pivot_evidence_root
        "1",                                # 12 pivot_fragment_count
        "0:1:0:0:1:1",                      # 13 pivot_fragments
        "1000",                             # 14 pivot_first_ts_ns
        "1001",                             # 15 pivot_last_ts_ns
        "0",                                # 16 pivot_last_bar_ordinal
        "53",                               # 17 confirmation_state_position
        "36",                               # 18 confirmation_group_ordinal
        str(visible - 1),                   # 19 confirmation_ts_ns
        str(visible),                       # 20 causal_visible_ts_ns
        "0",                                # 21 confirmation_bar_ordinal
        "0",                                # 22 causal_visible_bar_ordinal
        "false",                            # 23 pivot_retouch_order_uncertain
        "NA" if absent_delays else "0",     # 24 origin_to_visible_delay_bars_min
        "NA" if absent_delays else "1",     # 25 origin_to_visible_delay_bars_max
        "55000000",                         # 26 latency_from_pivot_ns_min
        "55000001",                         # 27 latency_from_pivot_ns_max
        "36",                               # 28 latency_from_pivot_groups_min
        "37",                               # 29 latency_from_pivot_groups_max
        "223717370",                        # 30 threshold_level_u6
        "223725000",                        # 31 confirmation_price_low_u6
        "223725001",                        # 32 confirmation_price_high_u6
        "1",                                # 33 confirmation_crossing_count
        digest("cross:" + label),           # 34 confirmation_crossing_set_root
        digest("group:" + label),           # 35 confirmation_group_root
        "7630",                             # 36 overshoot_low_u6
        "7631",                             # 37 overshoot_high_u6
        "HETEROGENEOUS_CROSSING_ENVELOPE",  # 38 confirmation_kind
        "0",                                # 39 confirmation_quality_mask
    ]


P = {name: digest("physical:" + name) for name in ("P1", "P2", "P3", "P4", "P5", "P6", "P7")}

#: (label, physical, policy, reversal, side, visible, absent_delays)
SESSION2_SIGNALS = [
    ("A1", "P1", "dc001", 1, "LOW", 1000, False),
    ("B1", "P2", "dc002", 2, "HIGH", 1000, False),
    ("B2", "P2", "dc002", 2, "HIGH", 1500, True),
    ("C1", "P3", "dc003", 3, "LOW", 1000, False),
    ("C2", "P3", "dc003", 3, "HIGH", 1000, False),
    ("D1", "P4", "dc004", 4, "LOW", 3000, False),
    ("E1", "P5", "dc005", 9, "LOW", 1000, False),
    ("F1", "P6", "dc006", 6, "LOW", 1000, False),
    ("F2", "P6", "dc006", 6, "LOW", 1200, False),
]


def build_signals(split_member: bool = False) -> dict[int, list[list[str]]]:
    """Ordinal -> its event rows. `split_member` moves F2 onto a second physical
    event, which is the card's multi-member fail-first mutation."""
    out: dict[int, list[list[str]]] = {}
    for ordinal in range(N_SESSIONS):
        day = DAYS[ordinal]
        if ordinal == 2:
            rows = []
            for label, physical, policy, reversal, side, visible, absent in SESSION2_SIGNALS:
                key = "P7" if (split_member and label == "F2") else physical
                rows.append(event_row(ordinal, day, label, P[key], policy, reversal, side,
                                      visible, absent))
            out[ordinal] = rows
        else:
            out[ordinal] = [
                event_row(ordinal, day, f"s{ordinal}_{i}", P["P1"], "dc001", 1,
                          "LOW" if i % 2 == 0 else "HIGH", 1000 + i)
                for i in range(2 + ordinal)
            ]
    return out


def render_event_signals(signals: dict[int, list[list[str]]], order: list[int]) -> str:
    lines = ["\t".join(EVENT_COLUMNS)]
    for ordinal in order:
        for row in signals[ordinal]:
            lines.append("\t".join(row))
    return "\n".join(lines) + "\n"


def render_t14(signals: dict[int, list[list[str]]], order: list[int],
               count_delta: dict[int, int] | None = None,
               root_override: dict[int, str] | None = None) -> str:
    count_delta = count_delta or {}
    root_override = root_override or {}
    lines = ["\t".join(T14_COLUMNS)]
    for position, ordinal in enumerate(order):
        rows = signals[ordinal]
        cells = ["0"] * len(T14_COLUMNS)
        cells[0] = str(position if order != sorted(order) else ordinal)
        cells[1] = DAYS[ordinal]
        cells[29] = root_override.get(ordinal, session_root(rows))
        cells[32] = str(len(rows) + count_delta.get(ordinal, 0))
        cells[49] = "three_wide"
        # every non-numeric metadata cell keeps a plausible shape; nothing but
        # ordinal/day/root/count is ever parsed.
        for index in (2, 3, 4, 10, 11, 12, 13, 14, 15, 28, 30, 31):
            cells[index] = digest(f"t14:{ordinal}:{index}")
        lines.append("\t".join(cells))
    return "\n".join(lines) + "\n"


