#: candidate -> its physical key in the RAW projection (the member set's own
#: physical event, which is what authentication must prove).
CANDIDATE_PHYSICAL = {
    "cand_A": "P1", "cand_B": "P2", "cand_C": "P3", "cand_D": "P4", "cand_E": "P5",
    "cand_G": "P1", "cand_N": "P1", "cand_S": "P1", "cand_U": "P1", "cand_X": "P1",
    "cand_F": "P6",
}


def member_cell(labels: list[str], form: str = "canonical") -> str:
    ids = sorted(digest(label) for label in labels)
    if form == "canonical":
        return ",".join(ids)
    if form == "unsorted":
        return ",".join(reversed(ids)) if len(ids) > 1 else ",".join([ids[0], ids[0]])
    if form == "duplicate":
        return ",".join(ids + [ids[-1]])
    if form == "uppercase":
        return ",".join([ids[0].upper()] + ids[1:])
    if form == "empty_token":
        return ",".join(ids) + ","
    if form == "whitespace":
        return ", ".join(ids) if len(ids) > 1 else " " + ids[0]
    raise ValueError(form)


def build_session2_rows(member_forms: dict[str, str] | None = None,
                        drop: set[str] | None = None,
                        registry_overrides: dict | None = None,
                        projection_overrides: dict | None = None):
    """Returns (registry_rows, projection_rows) for session ordinal 2."""
    member_forms = member_forms or {}
    drop = drop or set()
    registry_overrides = registry_overrides or {}
    projection_overrides = projection_overrides or {}
    registry_rows = []
    projection_rows = []
    for candidate, policy, reversal, visible, members, scorable in SESSION2_CANDIDATES:
        if candidate in drop:
            continue
        cell = member_cell(members, member_forms.get(candidate, "canonical"))
        reg = {
            "day": DAYS[2], "session_ordinal": "2", "row_kind": "CANDIDATE",
            "candidate_id": digest(candidate), "stream_policy_name": policy,
            "stream_reversal_bps": str(reversal), "member_signal_ids": cell,
            "member_count": str(len(members)),
            "visible_ts_ns": "NA" if visible is None else str(visible),
            "event_scorable": scorable, "physical_cluster_id": digest("cluster:" + candidate),
            "cluster_disposition": "FINAL", "cluster_size": "1",
        }
        reg.update(registry_overrides.get(candidate, {}))
        registry_rows.append(reg)
        raw = {
            "day": DAYS[2], "row_kind": "CANDIDATE", "candidate_id": digest(candidate),
            "stream_policy_name": policy, "stream_reversal_bps": str(reversal),
            "member_signal_ids": cell,
            "visible_ts_ns": "NA" if visible is None else str(visible),
            "physical_event_id": P[CANDIDATE_PHYSICAL[candidate]],
            "event_scorable": scorable, "side": "LEAK_IF_READ",
        }
        raw.update(projection_overrides.get(candidate, {}))
        projection_rows.append(raw)
    # A non-CANDIDATE row: the raw projection carries TRUTH rows too, and they
    # must never enter the join.
    projection_rows.append({
        "day": DAYS[2], "row_kind": "TRUTH", "candidate_id": digest("truth_row"),
        "stream_policy_name": "dc001", "stream_reversal_bps": "1",
        "member_signal_ids": digest("A1"), "visible_ts_ns": "2000",
        "physical_event_id": P["P1"], "side": "LEAK_IF_READ",
    })
    return registry_rows, projection_rows


def filler_rows(ordinal: int, count: int):
    """Small, self-consistent candidate rows for the sessions that are not the
    roster fixture, so every row group has real content."""
    registry_rows, projection_rows = [], []
    for i in range(count):
        candidate = f"s{ordinal}_c{i}"
        members = [f"s{ordinal}_{i}"]
        cell = member_cell(members)
        registry_rows.append({
            "day": DAYS[ordinal], "session_ordinal": str(ordinal), "row_kind": "CANDIDATE",
            "candidate_id": digest(candidate), "stream_policy_name": "dc001",
            "stream_reversal_bps": "1", "member_signal_ids": cell, "member_count": "1",
            "visible_ts_ns": str(5000 + i), "event_scorable": "true",
            "physical_cluster_id": digest("cluster:" + candidate),
        })
        projection_rows.append({
            "day": DAYS[ordinal], "row_kind": "CANDIDATE", "candidate_id": digest(candidate),
            "stream_policy_name": "dc001", "stream_reversal_bps": "1",
            "member_signal_ids": cell, "visible_ts_ns": str(5000 + i),
            "physical_event_id": P["P1"], "side": "LEAK_IF_READ",
        })
    return registry_rows, projection_rows


def materialise(rows_by_session: dict[int, list[dict]], names: list[str]):
    """Flattens per-session dict rows into column arrays plus group sizes."""
    values = {name: [] for name in names}
    sizes = []
    for ordinal in range(N_SESSIONS):
        rows = rows_by_session[ordinal]
        sizes.append(len(rows))
        for row in rows:
            for name in names:
                # A REQUIRED leaf has no null state at all, so an unset field is
                # the empty string, never a null.
                values[name].append(row.get(name, ""))
    return values, sizes


def build_tables(session2_registry, session2_projection):
    registry_by_session, projection_by_session = {}, {}
    for ordinal in range(N_SESSIONS):
        if ordinal == 2:
            registry_by_session[ordinal] = session2_registry
            projection_by_session[ordinal] = session2_projection
        else:
            reg, raw = filler_rows(ordinal, 2 + ordinal)
            registry_by_session[ordinal] = reg
            projection_by_session[ordinal] = raw
    return registry_by_session, projection_by_session


def write_session_index(path: str, sizes: list[int], row_override: dict[int, int] | None = None,
                        ordinal_override: dict[int, str] | None = None) -> None:
    row_override = row_override or {}
    ordinal_override = ordinal_override or {}
    lines = ["ordinal\tday\trows"]
    for ordinal in range(N_SESSIONS):
        lines.append("\t".join([
            ordinal_override.get(ordinal, str(ordinal)),
            DAYS[ordinal],
            str(row_override.get(ordinal, sizes[ordinal])),
        ]))
    with open(path, "w", encoding="ascii") as handle:
        handle.write("\n".join(lines) + "\n")


def write_text(path: str, body: str) -> None:
    with open(path, "w", encoding="ascii") as handle:
        handle.write(body)


def main(argv: list[str] | None = None) -> int:
    here = os.path.dirname(os.path.abspath(__file__))
    parser = argparse.ArgumentParser()
    parser.add_argument("--out-dir", default=os.path.join(here, "candidates"))
    parser.add_argument("--literals-path", default=None)
    args = parser.parse_args(argv)
    out = args.out_dir
    os.makedirs(out, exist_ok=True)
    literals_path = args.literals_path or os.path.join(out, "expected_literals.tsv")

    order = list(range(N_SESSIONS))

    # --- the TSV prefix fixtures ---------------------------------------------
    good = build_signals()
    write_text(os.path.join(out, "event_signals_good.tsv"), render_event_signals(good, order))
    write_text(os.path.join(out, "t14_bounds_good.tsv"), render_t14(good, order))
    write_text(os.path.join(out, "t14_bounds_bad_count.tsv"),
               render_t14(good, order, count_delta={2: 1}))
    bad_root = session_root(good[2])
    bad_root = bad_root[:-1] + ("0" if bad_root[-1] != "0" else "1")
    write_text(os.path.join(out, "t14_bounds_bad_root.tsv"),
               render_t14(good, order, root_override={2: bad_root}))

    # Non-monotone: the FILE goes 0,1,0,... and the census is permuted the same
    # way, so only the monotonicity law can catch it.
    permuted = [0, 1, 0, 2, 3, 4, 5]
    lines = ["\t".join(EVENT_COLUMNS)]
    census_lines = ["\t".join(T14_COLUMNS)]
    for position, ordinal in enumerate(permuted):
        for row in good[ordinal]:
            lines.append("\t".join(row))
        cells = ["0"] * len(T14_COLUMNS)
        cells[0] = str(ordinal)
        cells[1] = DAYS[ordinal]
        cells[29] = session_root(good[ordinal])
        cells[32] = str(len(good[ordinal]))
        cells[49] = "three_wide"
        census_lines.append("\t".join(cells))
    write_text(os.path.join(out, "event_signals_nonmonotone.tsv"), "\n".join(lines) + "\n")
    write_text(os.path.join(out, "t14_bounds_nonmonotone.tsv"), "\n".join(census_lines) + "\n")

    # Duplicate signal id inside one session.
    dup = build_signals()
    dup[2] = dup[2] + [dup[2][0]]
    write_text(os.path.join(out, "event_signals_duplicate_id.tsv"),
               render_event_signals(dup, order))
    write_text(os.path.join(out, "t14_bounds_duplicate_id.tsv"), render_t14(dup, order))

    # A carriage return inside an admitted row.
    cr = render_event_signals(good, order).replace("HETEROGENEOUS_CROSSING_ENVELOPE",
                                                   "HETEROGENEOUS\rENVELOPE", 1)
    write_text(os.path.join(out, "event_signals_carriage_return.tsv"), cr)

    # THE MULTI-MEMBER FAIL-FIRST: one member's physical id is moved to a second
    # physical event, and the census root is RECOMPUTED so the prefix seal still
    # passes. Only the member-physical-key check can catch this.
    split = build_signals(split_member=True)
    write_text(os.path.join(out, "event_signals_member_split.tsv"),
               render_event_signals(split, order))
    write_text(os.path.join(out, "t14_bounds_member_split.tsv"), render_t14(split, order))

    # --- the parquet fixtures --------------------------------------------------
    session2_registry, session2_projection = build_session2_rows()
    registry_by_session, projection_by_session = build_tables(session2_registry,
                                                             session2_projection)
    reg_values, reg_sizes = materialise(registry_by_session, REGISTRY_COLUMNS)
    raw_values, raw_sizes = materialise(projection_by_session, PROJECTION_COLUMNS)
    write_parquet(os.path.join(out, "registry_good.parquet"), REGISTRY_COLUMNS, reg_values,
                  reg_sizes, {"day", "candidate_id"})
    write_parquet(os.path.join(out, "projection_good.parquet"), PROJECTION_COLUMNS, raw_values,
                  raw_sizes, {"day", "candidate_id"})
    write_session_index(os.path.join(out, "registry_index.tsv"), reg_sizes)
    write_session_index(os.path.join(out, "projection_index.tsv"), raw_sizes)
    write_session_index(os.path.join(out, "projection_index_bad_rows.tsv"), raw_sizes,
                        row_override={2: raw_sizes[2] + 1})
    write_session_index(os.path.join(out, "projection_index_bad_ordinal.tsv"), raw_sizes,
                        ordinal_override={2: "7"})

    # THE SINGLETON FAIL-FIRST: only the candidate ROW's physical key moves.
    flipped_registry, flipped_projection = build_session2_rows(
        projection_overrides={"cand_A": {"physical_event_id": P["P7"]}})
    a, b = build_tables(flipped_registry, flipped_projection)
    values, sizes = materialise(b, PROJECTION_COLUMNS)
    write_parquet(os.path.join(out, "projection_singleton_key_flip.parquet"), PROJECTION_COLUMNS,
                  values, sizes, {"day", "candidate_id"})

    # A rowgroup whose `day` statistics claim a span rather than a single day.
    write_parquet(os.path.join(out, "projection_bad_day_stats.parquet"), PROJECTION_COLUMNS,
                  raw_values, raw_sizes, {"day", "candidate_id"},
                  stats_override={("day", 2): (b"2022-01-05", b"2022-01-06")})
    # A rowgroup whose statistics name a different day than the index does.
    write_parquet(os.path.join(out, "projection_wrong_day_stats.parquet"), PROJECTION_COLUMNS,
                  raw_values, raw_sizes, {"day", "candidate_id"},
                  stats_override={("day", 2): (b"2022-01-06", b"2022-01-06")})
    # A rowgroup with no `day` statistics at all.
    write_parquet(os.path.join(out, "projection_no_day_stats.parquet"), PROJECTION_COLUMNS,
                  raw_values, raw_sizes, {"candidate_id"})
    # One decoded row carrying a neighbour's day, with statistics that still
    # claim the indexed day: only the per-row check can catch it.
    smuggled_registry, smuggled_projection = build_session2_rows(
        projection_overrides={"cand_B": {"day": "2022-01-06"}})
    _, smuggled = build_tables(smuggled_registry, smuggled_projection)
    values, sizes = materialise(smuggled, PROJECTION_COLUMNS)
    write_parquet(os.path.join(out, "projection_smuggled_day.parquet"), PROJECTION_COLUMNS,
                  values, sizes, {"day", "candidate_id"},
                  stats_override={("day", 2): (b"2022-01-05", b"2022-01-05")})

    # THE PER-PROFILE REFUSAL FAMILY (ruling CC-003). Each of these is a lawful
    # parquet that the PUBLICATION profile must refuse by name: an OPTIONAL leaf
    # (lawful in the token corpus), a SNAPPY chunk, an INT64 leaf, and a leaf
    # with no converted type. None of them may be silently admitted.
    write_parquet(os.path.join(out, "projection_optional_leaves.parquet"), PROJECTION_COLUMNS,
                  raw_values, raw_sizes, {"day", "candidate_id"}, repetition=REP_OPTIONAL)
    write_parquet(os.path.join(out, "projection_snappy_codec.parquet"), PROJECTION_COLUMNS,
                  raw_values, raw_sizes, {"day", "candidate_id"}, codec=CODEC_SNAPPY)
    write_parquet(os.path.join(out, "projection_int64_leaf.parquet"), PROJECTION_COLUMNS,
                  raw_values, raw_sizes, {"day", "candidate_id"},
                  physical_override=("relation_count", TYPE_INT64))
    write_parquet(os.path.join(out, "projection_no_converted.parquet"), PROJECTION_COLUMNS,
                  raw_values, raw_sizes, {"day", "candidate_id"},
                  converted_override=("relation_count", None))

    # The join-disagreement family: the raw row contradicts the registry row.
    for name, override in (
        ("policy", {"stream_policy_name": "dc020"}),
        ("reversal", {"stream_reversal_bps": "99"}),
        ("visible", {"visible_ts_ns": "2001"}),
        ("members", {"member_signal_ids": member_cell(["C1"])}),
        ("physical_empty", {"physical_event_id": ""}),
    ):
        reg, raw = build_session2_rows(projection_overrides={"cand_A": override})
        _, tables = build_tables(reg, raw)
        values, sizes = materialise(tables, PROJECTION_COLUMNS)
        write_parquet(os.path.join(out, f"projection_join_{name}.parquet"), PROJECTION_COLUMNS,
                      values, sizes, {"day", "candidate_id"})

    # The malformed member-cell family, one registry per shape.
    for form in ("empty_token", "uppercase", "unsorted", "duplicate", "whitespace"):
        reg, raw = build_session2_rows(member_forms={"cand_B": form})
        tables, _ = build_tables(reg, raw)
        values, sizes = materialise(tables, REGISTRY_COLUMNS)
        write_parquet(os.path.join(out, f"registry_member_{form}.parquet"), REGISTRY_COLUMNS,
                      values, sizes, {"day", "candidate_id"})

    # THE STRICT event_scorable PARSE (consolidated review L2-F1): one registry
    # per unlawful spelling. `TRUE` and `1` are the two spellings a publication
    # drifts into; `yes` stands for everything else. Under `cell == "true"` all
    # three read as NOT SCORABLE and the candidate silently leaves the
    # population; under parse_bool they refuse the session.
    for form, cell in (("upper", "TRUE"), ("one", "1"), ("garbage", "yes")):
        reg, raw = build_session2_rows(
            registry_overrides={"cand_A": {"event_scorable": cell}})
        tables, _ = build_tables(reg, raw)
        values, sizes = materialise(tables, REGISTRY_COLUMNS)
        write_parquet(os.path.join(out, f"registry_scorable_{form}.parquet"), REGISTRY_COLUMNS,
                      values, sizes, {"day", "candidate_id"})

    # A registry whose stored member_count contradicts the derived count.
    reg, raw = build_session2_rows(registry_overrides={"cand_B": {"member_count": "3"}})
    tables, _ = build_tables(reg, raw)
    values, sizes = materialise(tables, REGISTRY_COLUMNS)
    write_parquet(os.path.join(out, "registry_member_count_mismatch.parquet"), REGISTRY_COLUMNS,
                  values, sizes, {"day", "candidate_id"})

    # A registry that repeats one candidate_id inside a session.
    reg, raw = build_session2_rows()
    reg = reg + [dict(reg[0])]
    tables, _ = build_tables(reg, raw)
    values, sizes = materialise(tables, REGISTRY_COLUMNS)
    write_parquet(os.path.join(out, "registry_duplicate_candidate.parquet"), REGISTRY_COLUMNS,
                  values, sizes, {"day", "candidate_id"})
    write_session_index(os.path.join(out, "registry_index_duplicate_candidate.tsv"), sizes)

    # THE LATE-SIBLING DELETION PAIR: cand_F is the strictly-latest-visible
    # candidate; deleting it must leave every earlier record bit-unchanged.
    reg, raw = build_session2_rows(drop={"cand_F"})
    reg_tables, raw_tables = build_tables(reg, raw)
    values, sizes = materialise(reg_tables, REGISTRY_COLUMNS)
    write_parquet(os.path.join(out, "registry_late_sibling_deleted.parquet"), REGISTRY_COLUMNS,
                  values, sizes, {"day", "candidate_id"})
    write_session_index(os.path.join(out, "registry_index_late_sibling_deleted.tsv"), sizes)
    values, sizes = materialise(raw_tables, PROJECTION_COLUMNS)
    write_parquet(os.path.join(out, "projection_late_sibling_deleted.parquet"), PROJECTION_COLUMNS,
                  values, sizes, {"day", "candidate_id"})
    write_session_index(os.path.join(out, "projection_index_late_sibling_deleted.tsv"), sizes)

    # --- the independently derived literals ------------------------------------
    literals = [
        "kind\tkey\tvalue",
        f"prefix\tstop_ordinal\t{STOP_ORDINAL}",
        f"prefix\tsession_count\t{N_SESSIONS}",
    ]
    text = render_event_signals(good, order)
    header_bytes = len(text.split("\n")[0]) + 1
    admitted = sum(len(good[o]) for o in range(STOP_ORDINAL + 1))
    stop_byte = header_bytes + sum(
        len("\t".join(row)) + 1 for o in range(STOP_ORDINAL + 1) for row in good[o])
    final_row_bytes = len("\t".join(good[STOP_ORDINAL][-1])) + 1
    literals += [
        f"prefix\theader_bytes\t{header_bytes}",
        f"prefix\tadmitted_rows\t{admitted}",
        f"prefix\tstop_byte_exclusive\t{stop_byte}",
        f"prefix\tfinal_row_bytes\t{final_row_bytes}",
        f"prefix\tfile_bytes\t{len(text)}",
    ]
    for ordinal in range(N_SESSIONS):
        literals.append(f"root\t{ordinal}\t{session_root(good[ordinal])}")
        literals.append(f"count\t{ordinal}\t{len(good[ordinal])}")
    literals.append("image\tsession2_row0\t" + signal_image(good[2][0]).hex())
    literals.append("image\tsession2_row2_absent_delays\t" + signal_image(good[2][2]).hex())
    literals.append("digest\tempty\t" + hashlib.sha256(b"").hexdigest())
    literals.append("digest\tabc\t" + hashlib.sha256(b"abc").hexdigest())
    for label in ("A1", "B1", "B2", "C1", "C2", "D1", "E1", "F1", "F2", "G1"):
        literals.append(f"signal_id\t{label}\t{digest(label)}")
    for candidate, *_ in SESSION2_CANDIDATES:
        literals.append(f"candidate_id\t{candidate}\t{digest(candidate)}")
    for name, value in sorted(P.items()):
        literals.append(f"physical\t{name}\t{value}")
    for ordinal, day in enumerate(DAYS):
        literals.append(f"day\t{ordinal}\t{day}")
    with open(literals_path, "w", encoding="ascii") as handle:
        handle.write("\n".join(literals) + "\n")

    print(f"wrote candidate fixtures to {out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
